import re


def solve(env, goal):
    goal_l = goal.lower()
    m = re.search(r"examine (?:the |a |an )?(.+?) (?:with|under|using) (?:the |a |an )?(.+?)(?:[.!]|$)", goal_l)
    if m:
        obj_type = m.group(1).strip()
        lamp_type = m.group(2).strip()
    else:
        obj_type = ""
        lamp_type = "lamp"
    obj_type = obj_type.rstrip(".!")
    lamp_type = lamp_type.rstrip(".!")
    obj_type = re.sub(r"^(?:a |an |the )", "", obj_type)
    lamp_type = re.sub(r"^(?:a |an |the )", "", lamp_type)

    seen = set()
    dropped = False
    held = None
    holding = False

    def obs():
        return env.observation

    def parse_obs(text):
        # returns (location_name or None, list of visible items)
        loc = None
        items = []
        lc = text.lower()
        mm = re.search(r"you arrive at ([^.\n]+?)[.]", text)
        if mm:
            loc = mm.group(1).strip().lower()
        mm2 = re.search(r"on the ([^,\n]+?), you see", text, re.I)
        if mm2:
            loc = mm2.group(1).strip().lower()
        for im in re.finditer(r"a ([a-z]+) (\d+)(?:,| and )", text):
            items.append((im.group(1).lower(), im.group(2)))
        return loc, items

    def norm_type(t):
        t = t.lower()
        t = re.sub(r"^(?:a |an |the )", "", t)
        return t

    def is_obj_of_type(name, t):
        n = norm_type(name)
        tt = norm_type(t)
        if n == tt:
            return True
        # plural / singular simple match
        if n.rstrip("s") == tt.rstrip("s"):
            return True
        return False

    def is_lamp_of_type(name, t):
        n = norm_type(name)
        tt = norm_type(t)
        if n == tt:
            return True
        # lamp variants: desklamp, tablelamp, floorlamp, lamp
        if tt.endswith("lamp"):
            if "lamp" in n:
                if tt == "lamp":
                    return True
                return tt in n or n == tt
        return False

    def inventory_items():
        txt = env.step("inventory")
        return txt

    def current_holding():
        txt = env.step("inventory")
        # inventory text lists held object
        return txt

    def take_item_from(loc, name, num):
        return env.step("take %s %s from %s" % (name, num, loc))

    def go(loc):
        return env.step("go to " + loc)

    def open_rec(loc):
        return env.step("open " + loc)

    def close_rec(loc):
        return env.step("close " + loc)

    def examine(loc):
        return env.step("examine " + loc)

    # Main loop: search for object, take it, then find lamp and use it
    # We need to explore receptacles. Use goal-independent scanning:
    # 1. Scan room for object and lamp.
    # 2. Take object.
    # 3. Go to lamp, use it.

    room_text = obs()
    # collect receptacle names from room text
    receptacles = []
    for mm in re.finditer(r"a ([a-z]+) (\d+)", room_text):
        name = mm.group(1).lower()
        num = mm.group(2)
        # things that look like receptacles: drawer, cabinet, fridge, microwave, safe, shelf, bed, dresser, garbagecan, sink, counter, table, desk, etc.
        if name in ("drawer", "cabinet", "fridge", "microwave", "safe", "shelf", "bed", "dresser", "garbagecan", "sink", "counter", "table", "desk", "closet", "box", "chest", "basin", "lamp", "desklamp", "tablelamp", "floorlamp"):
            receptacles.append((name, num))
        # also could be other objects; but we need to visit all to find things
        if (name, num) not in receptacles:
            receptacles.append((name, num))

    # We need to find object first. Visit receptacles, looking at contents.
    # Keep track of items seen by type.
    found_obj = None  # (loc, name, num)
    found_lamp = None  # (loc, name, num)

    # helper to scan a location
    def scan_loc(loc_name):
        nonlocal found_obj, found_lamp
        # need full location name with number: loc_name is like "shelf 9"
        go(loc_name)
        txt = obs()
        lc = txt.lower()
        # If closed receptacle, open it
        if "is closed" in lc or "closed" in lc and "you open" not in lc:
            open_rec(loc_name)
            txt = obs()
        loc, items = parse_obs(txt)
        # if loc is None, maybe still using loc_name
        if loc is None:
            loc = loc_name.lower()
        for name, num in items:
            if is_obj_of_type(name, obj_type) and found_obj is None:
                found_obj = (loc, name, num)
            if is_lamp_of_type(name, lamp_type) and found_lamp is None:
                found_lamp = (loc, name, num)
        # also try examining each item? Not needed; visible items are listed.
        # If nothing visible, maybe there are hidden things; but we already opened.
        return items

    # Visit each receptacle once
    visited = set()
    for name, num in receptacles:
        loc_name = name + " " + num
        if loc_name in visited:
            continue
        visited.add(loc_name)
        scan_loc(loc_name)
        if found_obj is not None and found_lamp is not None:
            break

    # If object not found, try opening all closed receptacles and re-scan maybe.
    if found_obj is None:
        # second pass: open everything and check
        for name, num in receptacles:
            loc_name = name + " " + num
            go(loc_name)
            txt = obs()
            if "is closed" in txt.lower():
                open_rec(loc_name)
                scan_loc(loc_name)
            if found_obj is not None:
                break

    # If lamp not found, maybe it's in inventory? Or search more.
    if found_lamp is None:
        # Try using any lamp we may have seen; maybe lamp type is generic "lamp" but object name is desklamp.
        # Re-scan all locations for any lamp-like object.
        for name, num in receptacles:
            loc_name = name + " " + num
            go(loc_name)
            txt = obs()
            loc, items = parse_obs(txt)
            for iname, inum in items:
                if "lamp" in iname.lower():
                    found_lamp = (loc or loc_name.lower(), iname, inum)
                    break
            if found_lamp:
                break

    if found_obj is None:
        return

    # Take the object
    loc, name, num = found_obj
    # Ensure we are at loc
    go(loc)
    # If receptacle closed, open
    txt = obs()
    if "is closed" in txt.lower():
        open_rec(loc)
    res = take_item_from(loc, name, num)
    # if take failed (e.g., because item moved), try again after opening
    if "nothing happens" in res.lower():
        open_rec(loc)
        res = take_item_from(loc, name, num)

    # Now find lamp and use it
    if found_lamp is not None:
        lloc, lname, lnum = found_lamp
        go(lloc)
        txt = obs()
        if "is closed" in txt.lower():
            open_rec(lloc)
        env.step("use %s %s" % (lname, lnum))
    else:
        # fallback: try to use any lamp in inventory? Not possible.
        pass

    return
